#include "mspa/psychology/emotions.hpp"
#include <algorithm>
#include <cmath>
namespace mspa {namespace {void merge(AgentPsychState&a,BasicEmotion k,float x,PsychTime now){if(x<=0.001f)return;auto it=std::find_if(a.emotions.begin(),a.emotions.end(),[&](const auto&e){return e.kind==k;});if(it==a.emotions.end())a.emotions.push_back({k,std::clamp(x,0.0f,1.0f),now,now});else{it->intensity=std::clamp(it->intensity+(1.0f-it->intensity)*x,0.0f,1.0f);it->updated_at=now;}}}
void EmotionSystem::apply(AgentPsychState&a,const AppraisalVector&v,PsychTime now)const{if(v.relevance<=0)return;const float rel=v.relevance;const float neg=std::max(0.0f,-v.consequence),pos=std::max(0.0f,v.consequence);merge(a,BasicEmotion::Joy,rel*pos*(0.6f+0.4f*v.certainty),now);merge(a,BasicEmotion::Sadness,rel*neg*(1.0f-v.control)*(1.0f-0.4f*v.agency),now);merge(a,BasicEmotion::Fear,rel*neg*(1.0f-v.control)*(0.5f+0.5f*v.certainty),now);merge(a,BasicEmotion::Anger,rel*neg*v.agency*v.intentionality*(0.45f+0.55f*v.control),now);merge(a,BasicEmotion::Anxiety,rel*(0.55f*v.expectation_error+0.45f*(1.0f-v.certainty))*(0.5f+0.5f*neg),now);merge(a,BasicEmotion::Aversion,rel*std::max(0.0f,-v.norm_alignment)*(0.5f+0.5f*neg),now);}
void EmotionSystem::decay(AgentPsychState&a,PsychTime now,float rate)const{rate=std::max(0.0f,rate);const float stability=std::clamp(a.personality.stability,0.0f,1.0f);for(auto&e:a.emotions){if(now<e.updated_at)continue;const float elapsed=static_cast<float>(now.ticks()-e.updated_at.ticks());const float k=rate*(0.6f+0.8f*stability);e.intensity=std::max(0.0f,e.intensity-elapsed*k);e.updated_at=now;}a.emotions.erase(std::remove_if(a.emotions.begin(),a.emotions.end(),[](const auto&e){return e.intensity<=0.0001f;}),a.emotions.end());}
float EmotionSystem::intensity(const AgentPsychState&a,BasicEmotion k)const noexcept{auto it=std::find_if(a.emotions.begin(),a.emotions.end(),[&](const auto&e){return e.kind==k;});return it==a.emotions.end()?0.0f:it->intensity;}}
